import React, { useState } from "react";
import TeacherLoggedHome_CreateNewTask from "./TeacherLoggedHome_CreateNewTask"; // Import the new component
import './TeacherLoggedHome.css';

const TeacherLoggedHome = ({ userId }) => {
    const [isPopupOpen, setPopupOpen] = useState(false);

    const openPopup = () => {
        setPopupOpen(true);
    };

    const closePopup = () => {
        setPopupOpen(false);
    };

    return (
        <div className="teacher-home-container">
            <h1 className="teacher-title">👨‍🏫 Welcome Back, Teacher! 🍎</h1>
            <p className="teacher-subtitle">
                This platform helps you track student performance by creating tasks that mirror real assignments.
                Assign topic tags to each question to help students identify their strengths and areas for improvement.
            </p>

            <ul className="teacher-feature-list">
                <li>📌 <strong>Track student progress:</strong> Visualize their learning journey.</li>
                <li>🎯 <strong>Identify weak spots:</strong> Help students focus on areas they need to improve.</li>
                <li>📊 <strong>Data-driven insights:</strong> Use radar charts to analyze topic performance.</li>
            </ul>

            <div className="button-container">
                <button className="create-button" onClick={openPopup}>➕ Create New Task</button>
            </div>

            {/* pass userId directly to the CreateNewTask component */}
            <TeacherLoggedHome_CreateNewTask
                isOpen={isPopupOpen}
                onClose={closePopup}
                teacherId={userId}
            />
        </div>
    );
}

export default TeacherLoggedHome;
