import React, { useEffect, useState, useRef } from 'react';
import { Bar, Radar } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend,
    RadarController,
    RadialLinearScale,
    PointElement,
    LineElement,
    Filler
} from 'chart.js';
import './StudentTasks_CompleteNewTask.css';
import { supabase } from '../../supabaseClient';

ChartJS.register(
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend,
    RadarController,
    RadialLinearScale,
    PointElement,
    LineElement,
    Filler
);

const StudentTasks_VisualFeedback = ({ studentId, taskId, onClose }) => {
    const [chartData, setChartData] = useState(null);
    const [tagChartData, setTagChartData] = useState(null);
    const [radarChartData, setRadarChartData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [activeTab, setActiveTab] = useState('graph1');
    const [taskName, setTaskName] = useState(null);

    // Define references for the charts
    const chartRef1 = useRef(null);
    const chartRef2 = useRef(null);
    const chartRef3 = useRef(null);

    useEffect(() => {
        const fetchTaskData = async () => {
            setLoading(true);
            try {
                const { data: completionData, error: completionError } = await supabase
                    .from('task_completions')
                    .select('scores')
                    .eq('student_id', studentId)
                    .eq('task_id', taskId)
                    .single();

                if (completionError) throw completionError;
                if (!completionData) throw new Error('No task completion data found');

                const scores = completionData.scores.map(item => item.score);

                const { data: taskData, error: taskError } = await supabase
                    .from('tasks')
                    .select('task_name, questions')
                    .eq('id', taskId)
                    .single();

                if (taskError) throw taskError;
                if (!taskData) throw new Error('No task data found');

                const questions = taskData.questions;
                setTaskName(taskData.task_name);
                const questionIds = questions.map(q => `Q${q.question_number}`);
                const correctMarks = scores;
                const incorrectMarks = questions.map((q, i) => parseInt(q.total_marks, 10) - correctMarks[i]);

                setChartData({
                    labels: questionIds,
                    datasets: [
                        {
                            label: 'Correct Marks',
                            data: correctMarks,
                            backgroundColor: 'green',
                        },
                        {
                            label: 'Incorrect Marks',
                            data: incorrectMarks,
                            backgroundColor: 'red',
                        },
                    ],
                });

                let tagData = {};
                questions.forEach((q, i) => {
                    const correctMark = correctMarks[i];
                    const totalMark = parseInt(q.total_marks, 10);
                    q.tags.forEach(tag => {
                        if (!tagData[tag]) {
                            tagData[tag] = { correctMarks: 0, totalMarks: 0 };
                        }
                        tagData[tag].correctMarks += correctMark;
                        tagData[tag].totalMarks += totalMark;
                    });
                });

                const tagLabels = Object.keys(tagData);
                const tagCorrectMarks = tagLabels.map(tag => tagData[tag].correctMarks);
                const tagTotalMarks = tagLabels.map(tag => tagData[tag].totalMarks);

                setTagChartData({
                    labels: tagLabels,
                    datasets: [
                        {
                            label: 'Correct Marks by Tag',
                            data: tagCorrectMarks,
                            backgroundColor: 'green',
                        },
                        {
                            label: 'Total Marks by Tag',
                            data: tagTotalMarks,
                            backgroundColor: 'blue',
                        },
                    ],
                });

                setRadarChartData({
                    labels: tagLabels,
                    datasets: [
                        {
                            label: 'Accuracy by Tag',
                            data: tagCorrectMarks.map((correctMark, index) => (correctMark / tagTotalMarks[index]) * 100), // Accuracy as percentage
                            backgroundColor: 'rgba(255, 99, 71, 0.2)', // Light red for inner shading
                            borderColor: 'red', // Red line
                            pointBackgroundColor: 'red', // Red points
                            fill: true, // Fill the radar chart
                        },
                    ],
                });

            } catch (err) {
                console.error('Error fetching task data:', err.message);
                setError(err.message);
            } finally {
                setLoading(false);
            }
        };

        fetchTaskData();
    }, [studentId, taskId]);

    const handleTabChange = (tab) => {
        setActiveTab(tab);
    };

    const downloadChart = (chartRef) => {
        if (chartRef.current) {
            const chart = chartRef.current;
            const canvas = chart.canvas;

            // Removed the forced white background
            const imageUrl = chart.toBase64Image();
            const link = document.createElement('a');
            link.href = imageUrl;
            link.download = `chart_${Date.now()}.jpg`;
            link.click();
        } else {
            console.error("Chart instance is not available yet.");
        }
    };

    if (loading) return <p>Loading task results...</p>;
    if (error) return <p>Error: {error}</p>;

    return (
        <div className="popup-container">
            <div className="popup">
                <h2>"{taskName}" Results</h2>
                <div className="tabs">
                    <button
                        className={activeTab === 'graph1' ? 'active' : ''}
                        onClick={() => handleTabChange('graph1')}
                    >
                        By Question
                    </button>
                    <button
                        className={activeTab === 'graph2' ? 'active' : ''}
                        onClick={() => handleTabChange('graph2')}
                    >
                        By Topic
                    </button>
                    <button
                        className={activeTab === 'graph3' ? 'active' : ''}
                        onClick={() => handleTabChange('graph3')}
                    >
                        Radar Graph
                    </button>
                </div>
                <div className="tab-content">
                    {activeTab === 'graph1' && chartData && (
                        <div>
                            <Bar
                                ref={chartRef1}
                                data={chartData}
                                options={{
                                    responsive: true,
                                    plugins: {
                                        legend: { position: 'top' },
                                        title: { display: true, text: `Task ${taskId} Results` },
                                    },
                                    scales: {
                                        y: { beginAtZero: true },
                                    },
                                }}
                            />
                            <div className="buttons">
                                <button onClick={() => downloadChart(chartRef1)} className="download-button">Download</button>
                            </div>
                        </div>
                    )}
                    {activeTab === 'graph2' && tagChartData && (
                        <div>
                            <Bar
                                ref={chartRef2}
                                data={tagChartData}
                                options={{
                                    responsive: true,
                                    plugins: {
                                        legend: { position: 'top' },
                                        title: { display: true, text: `Task ${taskId} Tags` },
                                    },
                                    scales: {
                                        y: { beginAtZero: true },
                                        x: {
                                            ticks: {
                                                maxRotation: 90,
                                                minRotation: 90,
                                            },
                                        },
                                    },
                                }}
                            />
                            <div className="buttons">
                                <button onClick={() => downloadChart(chartRef2)} className="download-button">Download</button>
                            </div>
                        </div>
                    )}
                    {activeTab === 'graph3' && radarChartData && (
                        <div>
                            <Radar
                                ref={chartRef3}
                                data={radarChartData}
                                options={{
                                    responsive: true,
                                    plugins: {
                                        legend: { position: 'top' },
                                        title: { display: true, text: `Radar Chart: Task ${taskId} Tags` },
                                    },
                                    scale: {
                                        ticks: {
                                            beginAtZero: true,
                                        },
                                    },
                                    elements: {
                                        line: {
                                            borderColor: 'red', // Red line color
                                            borderWidth: 2, // Set line width
                                        },
                                    },
                                }}
                            />
                            <div className="buttons">
                                <button onClick={() => downloadChart(chartRef3)} className="download-button">Download</button>
                            </div>
                        </div>
                    )}
                </div>
                <div className="buttons">
                    <button onClick={onClose} className="close-button">X</button>
                </div>
            </div>
        </div>
    );
};

export default StudentTasks_VisualFeedback;
